{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.BANANA_CLUB_PRODUCT_MARKETING_CONSOLIDATED AS SELECT CAST(Adset_Name AS STRING) AS ADSET_NAME, CAST(Adset_ID AS STRING) AS ADSET_ID, CAST(ad_id AS STRING) AS AD_ID, CAST(ad_name AS STRING) AS AD_NAME, CAST(Account_Name AS STRING) AS ACCOUNT_NAME, CAST(Account_ID AS STRING) AS ACCOUNT_ID, CAST(Campaign_Name AS STRING) AS CAMPAIGN_NAME, CAST(Campaign_ID AS STRING) AS CAMPAIGN_ID, COALESCE(fc.PRODUCT_ID,SC.PRODUCT_ID) AS PRODUCT_ID, COALESCE(FC.VARIANT_ID,SSF.VARIANT_ID) AS VARIANT_ID, CAST(Date AS DATE) AS DATE, CAST(NULL AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', Date) AS DAY_OF_WEEK, EXTRACT(YEAR FROM Date) AS YEAR, EXTRACT(MONTH FROM Date) AS MONTH, CAST(Channel AS STRING) AS Channel, CAST(Account AS STRING) AS ACCOUNT, CAST(Clicks AS FLOAT64) AS CLICKS, CAST(Spend AS FLOAT64) AS SPEND, CAST(Impressions AS FLOAT64) AS IMPRESSIONS, CAST(Conversions AS FLOAT64) AS CONVERSIONS, CAST(Conversion_Value AS FLOAT64) AS CONVERSION_VALUE, COALESCE(SC.SKU,SSF.SKU) AS SKU FROM maplemonk.BananaClub_db_Product_FACEBOOK_CONSOLIDATED fc LEFT JOIN ( SELECT SKU, PRODUCT_ID, FROM `maplemonk.bananaclub_SHOPIFY_FACT_ITEMS` QUALIFY ROW_NUMBER() OVER (PARTITION BY PRODUCT_ID order by sku desc) = 1 ) sc ON FC.product_id = sc.PRODUCT_ID LEFT JOIN ( SELECT SKU, VARIANT_ID, FROM `maplemonk.bananaclub_SHOPIFY_FACT_ITEMS` QUALIFY ROW_NUMBER() OVER (PARTITION BY VARIANT_ID order by sku desc) = 1 ) SSF ON FC.VARIANT_ID = SSF.VARIANT_ID UNION ALL SELECT CAST(ADSET_NAME AS STRING) AS ADSET_NAME, CAST(ADSET_ID AS STRING) AS ADSET_ID, CAST(AD_ID AS STRING) AS AD_ID, CAST(AD_NAME AS STRING) AS AD_NAME, CAST(ACCOUNT_NAME AS STRING) AS ACCOUNT_NAME, CAST(ACCOUNT_ID AS STRING) AS ACCOUNT_ID, CAST(CAMPAIGN_NAME AS STRING) AS CAMPAIGN_NAME, CAST(CAMPAIGN_ID AS STRING) AS CAMPAIGN_ID, COALESCE(GC.PRODUCT_ID,SC.PRODUCT_ID) AS PRODUCT_ID, COALESCE(GC.VARIANT_ID,SSC.VARIANT_ID) AS VARIANT_ID, CAST(DATE AS DATE) AS DATE, CAST(AD_TYPE AS STRING) AS AD_TYPE, CAST(AD_STRENGTH AS STRING) AS AD_STRENGTH, CAST(AD_NETWORK_TYPE AS STRING) AS AD_NETWORK_TYPE, CAST(AD_FINAL_URL AS STRING) AS AD_FINAL_URL, CAST(DAY_OF_WEEK AS STRING) AS DAY_OF_WEEK, CAST(YEAR AS INT64) AS YEAR, CAST(MONTH AS INT64) AS MONTH, CAST(Channel AS STRING) AS Channel, CAST(ACCOUNT AS STRING) AS ACCOUNT, CAST(clicks AS FLOAT64) AS CLICKS, CAST(spend AS FLOAT64) AS SPEND, CAST(Impressions AS FLOAT64) AS IMPRESSIONS, CAST(Conversions AS FLOAT64) AS CONVERSIONS, CAST(Conversion_Value AS FLOAT64) AS CONVERSION_VALUE, COALESCE(SC.SKU,SSC.SKU) AS SKU FROM maplemonk.Banana_club_db_Product_GOOGLEADS_CONSOLIDATED GC LEFT JOIN ( SELECT SKU, PRODUCT_ID, FROM `maplemonk.bananaclub_SHOPIFY_FACT_ITEMS` QUALIFY ROW_NUMBER() OVER (PARTITION BY PRODUCT_ID order by sku desc) = 1 ) sc ON GC.product_id = sc.PRODUCT_ID LEFT JOIN ( SELECT SKU, VARIANT_ID, FROM `maplemonk.bananaclub_SHOPIFY_FACT_ITEMS` QUALIFY ROW_NUMBER() OVER (PARTITION BY VARIANT_ID order by sku desc) = 1 ) SSC ON GC.VARIANT_ID = SSC.VARIANT_ID;",
                    "transaction": true
                }
